# Spatial broad-context inference, with full panel qualification and all fixed distance variants.
args<-commandArgs(trailingOnly=TRUE);r<-normalizePath(args[1]);unit<-args[2];inp<-file.path(r,'imaging',unit);out<-file.path(inp,'CellChat_v2');stopifnot(!dir.exists(out));dir.create(out)
suppressPackageStartupMessages(library(CellChat));suppressPackageStartupMessages(library(Matrix));future::plan('sequential');set.seed(2026110703)
x<-readMM(file.path(inp,'normalized_expression_PRIVATE.mtx'));genes<-readLines(file.path(inp,'genes.tsv'));meta<-read.delim(file.path(inp,'metadata_PRIVATE.tsv'),row.names=1,check.names=FALSE);rownames(x)<-genes;colnames(x)<-rownames(meta);stopifnot(nrow(meta)==ncol(x),!anyDuplicated(genes),all(is.finite(x@x)),all(x@x>=0))
db<-readRDS(file.path(r,'sources/CellChatDB_2_2_0/database_PRIVATE.rds'));resolve<-function(name){if(is.na(name)||name=='')return(character());if(name%in%rownames(db$complex)){v<-as.character(db$complex[name,]);return(v[!is.na(v)&v!=''])};if(name%in%rownames(db$cofactor)){v<-as.character(db$cofactor[name,]);return(v[!is.na(v)&v!=''])};return(name)}
fields<-intersect(c('ligand','receptor','agonist','antagonist','co_A_receptor','co_I_receptor'),names(db$interaction));measurement<-lapply(seq_len(nrow(db$interaction)),function(i){row<-db$interaction[i,];gg<-unique(unlist(lapply(as.character(row[,fields]),resolve)));missing<-setdiff(gg,genes);data.frame(interaction=rownames(db$interaction)[i],category=row$annotation,n_required_components=length(gg),missing_components=paste(missing,collapse=';'),complete_measured=length(missing)==0 && length(gg)>0,protein=row$annotation!='Non-protein Signaling')});measurement<-do.call(rbind,measurement);write.table(measurement,file.path(out,'database_component_qualification.tsv'),sep='\t',quote=FALSE,row.names=FALSE);db$interaction<-db$interaction[measurement$complete_measured&measurement$protein,,drop=FALSE]
if(nrow(db$interaction)==0){jsonlite::write_json(list(status='UNASSESSABLE_NO_FULLY_MEASURED_PROTEIN_INTERACTIONS'),file.path(out,'complete.json'),auto_unbox=TRUE);quit(status=0)}
variants<-expand.grid(interaction.range=c(100,250),contact.range=c(10,20));groups<-sort(unique(meta$source_FOV));ready<-list();allmin<-numeric()
for(i in seq_along(groups)){
 ix<-which(meta$source_FOV==groups[i]);mm<-meta[ix,,drop=FALSE];nn<-table(mm$broad);ix<-ix[mm$broad%in%names(nn)[nn>=10]];mm<-meta[ix,,drop=FALSE]
 if(length(unique(mm$broad))<2)next
 mm$labels<-factor(mm$broad);mm$group<-mm$labels;mm$samples<-factor('one_independent_geometry_unit');coords<-mm[,c('x_um','y_um')];d<-computeRegionDistance(coordinates=coords,meta=mm,interaction.range=250,ratio=1,tol=5,k.min=10,contact.dependent=TRUE,contact.range=10,do.symmetric=TRUE);dd<-d$d.spatial;diag(dd)<-NA;vals<-dd[is.finite(dd)&dd>0]
 if(!length(vals))next
 allmin<-c(allmin,min(vals));ready[[length(ready)+1]]<-list(ix=ix,meta=mm,code=sprintf('F%04d',i))
}
if(!length(ready)){
 jsonlite::write_json(list(status='UNASSESSABLE_NO_TWO_SUPPORTED_SPATIALLY_PROXIMAL_GROUPS',n_FOV_requested=length(groups),n_qualified_interactions=nrow(db$interaction)),file.path(out,'complete.json'),auto_unbox=TRUE,pretty=TRUE);quit(status=0)
}
# Geometry-only scale shared by all FOVs and variants of this native imaging input.
scale.distance<-1.5/min(allmin);receipts<-list();k<-0
for(fov in ready){
 for(v in seq_len(nrow(variants))){
  k<-k+1;tag<-paste0(fov$code,'_r',variants$interaction.range[v],'_c',variants$contact.range[v]);start<-Sys.time();dest<-file.path(out,tag);dir.create(dest);mm<-fov$meta
  cc<-createCellChat(object=x[,fov$ix,drop=FALSE],meta=mm,group.by='labels',datatype='spatial',coordinates=mm[,c('x_um','y_um')],spatial.factors=data.frame(ratio=1,tol=5));cc@DB<-db;cc<-subsetData(cc);cc<-identifyOverExpressedGenes(cc,do.DE=FALSE,min.cells=10);cc<-identifyOverExpressedInteractions(cc,variable.both=FALSE)
  cc<-computeCommunProb(cc,type='truncatedMean',trim=0.1,raw.use=TRUE,population.size=FALSE,distance.use=TRUE,interaction.range=variants$interaction.range[v],scale.distance=scale.distance,k.min=10,contact.dependent=TRUE,contact.range=variants$contact.range[v],nboot=100,seed.use=2026110703)
  cc<-filterCommunication(cc,min.cells=10);stopifnot(all(is.finite(cc@net$prob)),all(cc@net$prob>=0),all(is.finite(cc@net$pval)),all(cc@net$pval>=0&cc@net$pval<=1));flag<-cc@net$prob>0&cc@net$pval<0.05;qual<-array(p.adjust(as.vector(cc@net$pval),method='BH'),dim=dim(cc@net$pval),dimnames=dimnames(cc@net$pval));counts<-apply(flag,c(1,2),sum);qcounts<-apply(cc@net$prob>0&qual<.05,c(1,2),sum);allpairs<-expand.grid(source=rownames(counts),target=colnames(counts),stringsAsFactors=FALSE);allpairs$n_candidate_CCI<-as.vector(counts);allpairs$n_BH_CCI<-as.vector(qcounts);write.table(allpairs,file.path(dest,'identity_pair_counts.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
  ind<-which(flag,arr.ind=TRUE);candidates<-if(nrow(ind))data.frame(source=dimnames(flag)[[1]][ind[,1]],target=dimnames(flag)[[2]][ind[,2]],interaction=dimnames(flag)[[3]][ind[,3]],prob=cc@net$prob[ind],p=cc@net$pval[ind],BH_q=qual[ind]) else data.frame(source=character(),target=character(),interaction=character(),prob=numeric(),p=numeric(),BH_q=numeric());write.table(candidates,file.path(dest,'candidate_LR.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
  saveRDS(list(prob=cc@net$prob,pval=cc@net$pval,metadata=list(interaction_range=variants$interaction.range[v],contact_range=variants$contact.range[v],scale_distance=scale.distance,coordinate_unit='micrometre',within_FOV_only=TRUE)),file.path(dest,'probability_arrays_PRIVATE.rds'))
  # Independent readback of saved arrays and strict nominal count algebra; full BH also saved above.
  zz<-readRDS(file.path(dest,'probability_arrays_PRIVATE.rds'));expected<-apply(zz$prob>0&zz$pval<.05,c(1,2),sum);stopifnot(identical(expected,counts),sum(counts)==nrow(candidates),sum(qcounts)==sum(zz$prob>0&array(p.adjust(as.vector(zz$pval),'BH'),dim=dim(zz$pval))<.05))
  rec<-list(status='SPATIAL_CELLCHAT_NATIVE_UNIT_VARIANT_FINISHED_AND_ARRAY_READBACK_PASS',UTC=format(Sys.time(),'%Y-%m-%dT%H:%M:%SZ',tz='UTC'),seconds=as.numeric(difftime(Sys.time(),start,units='secs')),n_cells=length(fov$ix),n_labels=nlevels(cc@idents),n_candidate_identity_pair_LR_events=nrow(candidates),n_BH_identity_pair_LR_events=sum(qcounts),n_interactions_in_model=dim(flag)[3],interaction_range_um=variants$interaction.range[v],contact_range_um=variants$contact.range[v],scale_distance=scale.distance,nboot=100,CellChat=as.character(packageVersion('CellChat')),protein_only_and_all_optional_components_measured=TRUE,broad_context_not_exact_CM_replication=TRUE,no_contact_causal_patient_claim=TRUE)
  jsonlite::write_json(rec,file.path(dest,'complete.json'),pretty=TRUE,auto_unbox=TRUE);receipts[[k]]<-rec;jsonlite::write_json(list(n_completed_variants=k,n_requested_variants=length(ready)*4),file.path(out,'progress.json'),auto_unbox=TRUE)
 }
}
jsonlite::write_json(list(status='ALL_FIXED_SPATIAL_CELLCHAT_VARIANTS_FINISHED_ARRAY_READBACK_PASS',UTC=format(Sys.time(),'%Y-%m-%dT%H:%M:%SZ',tz='UTC'),n_FOV_requested=length(groups),n_FOV_eligible=length(ready),n_variants=length(receipts),scale_distance=scale.distance,scale_selected_only_from_geometry=TRUE,p_values_are_CellChat_expression_permutations_not_spatial_null=TRUE,all_results=receipts),file.path(out,'complete_PRIVATE.json'),pretty=TRUE,auto_unbox=TRUE)
